type ProduceListing = {
  id: string
  name: string
  variety?: string
  emoji?: string
  image_url?: string
  image_urls?: string[] | null
  method?: string
  status: string
  price_tier_1_price?: number
  price_tier_1_qty?: number
  price_tier_2_price?: number
  price_tier_2_qty?: number
  price_tier_3_price?: number
  price_tier_3_qty?: number
  stock_qty?: number
  unit?: string
  available_to?: string
  rating_avg?: number | null
  review_count?: number | null
  // Non-cancelled/declined order count for this listing — powers "sort by
  // Purchases". Attached by /api/produce and /api/produce/search.
  purchase_count?: number | null
  farmer_id: string
  farmer?: Farmer
  // Shelf life set on the listing itself (produce Edit form) — used as the
  // fallback when the latest logged harvest doesn't carry its own.
  shelf_life_days?: number | null
  // Harvest date/time set on the listing itself (produce Edit form). Drives the
  // clock when no separate `harvests` row has been logged for this produce.
  harvest_date?: string | null
  // Latest harvest for this produce (template), attached client-side from the
  // `harvests` table — drives the "Harvested 2 hours ago" clock on the card.
  latest_harvested_at?: string | null
  latest_shelf_life_days?: number | null
}

// One logged harvest of a produce (template). The main grid shows a separate
// card per harvest — so 3 harvests of the same Banana are 3 cards, each with its
// own pick date/time, shelf life and stock — while inheriting everything else
// (photos, price, farmer, quality) from the produce_listing. Reads the
// `harvests` table (scripts/harvests-migration.sql).
type GridHarvest = {
  id: string
  harvested_at: string

  document.addEventListener('visibilitychange', handleVisibility)
  return () => document.removeEventListener('visibilitychange', handleVisibility)
}, [])

// Fetch latest UPI IDs and QR codes for all farmers in cart when sheet opens
useEffect(() => {
  const farmerIds = [...new Set(items.map((i) => i.farmerId).filter(Boolean))]
  if (farmerIds.length === 0) return
  supabase
    .from('farmers')
    .select('id, upi_id, upi_qr_code_url, cod_enabled')
    .in('id', farmerIds)
    .then(({ data }) => {
      if (!data) return
      const upiMap: Record<string, string> = {}
      const qrMap: Record<string, string> = {}
      const codMap: Record<string, boolean> = {}
      for (const f of data) {
        if (f.upi_id) upiMap[f.id] = f.upi_id
        if (f.upi_qr_code_url) qrMap[f.id] = f.upi_qr_code_url
        codMap[f.id] = f.cod_enabled === true
      }
      setLiveUpiIds(upiMap)
      setLiveQrUrls(qrMap)
      setLiveCodEnabled(codMap)
    })
}, [items])

useEffect(() => {
  setName(info.name)
  setPhone(info.phone)
}, [info])

// When the consumer logs in, prefer their authenticated profile over any
// stale form data from the legacy localStorage entry.
useEffect(() => {
  if (!consumer) return
  if (consumer.name) setName(consumer.name)
  if (consumer.phone) setPhone(consumer.phone)
}, [consumer])

// Group items by farmer
const byFarmer = items.reduce<Record<string, CartItem[]>>((acc, item) => {
  (acc[item.farmerId] = acc[item.farmerId] ?? []).push(item)
  return acc
}, {})
const farmerGroups = Object.values(byFarmer)

