const deliveryDetailsMissing = needsAddress
  && (deliveryAddress.trim().length < 10 || !deliveryCity.trim() || !/^\d{6}$/.test(deliveryPincode.trim()))
const detailsMissing = baseDetailsMissing || deliveryDetailsMissing

